from math import isqrt


def solve(value):
    result = []
    for number in value:
        if number < 2:
            result.append(False)
            continue

        prime = True
        for divisor in range(2, isqrt(number) + 1):
            if number % divisor == 0:
                prime = False
                break
        result.append(prime)

    return result
